(7660406, 1248190, 114285, '<td valign="top">Amazing, really amazing!</td>', 'Amazing, really amazing!', '2020-04-28 10:18:03.000000', NULL, 1),
(7660415, 1248230, 138630, '<td valign="top">Lovely tones, shapes, and, yes, balance.</td>', 'Lovely tones, shapes, and, yes, balance.', '2020-04-28 12:36:46.000000', NULL, 1),
(7660416, 1248251, 138630, '<td valign="top">Cool textures, colors, and patterns.  I don''t find the shadow particularly compelling here.</td>', 'Cool textures, colors, and patterns.  I don''t find the shadow particularly compelling here.', '2020-04-28 12:37:27.000000', NULL, 1),
(7660417, 1248158, 138630, '<td valign="top">I always enjoy the lines of reeds or grasses reflected in water.  Tones are a bit muddy for me here.</td>', 'I always enjoy the lines of reeds or grasses reflected in water.  Tones are a bit muddy for me here.', '2020-04-28 12:38:17.000000', NULL, 1),
(7660418, 1248264, 138630, '<td valign="top">I would like better balance in exposure and focus.  I also find the right 2/3 more interesting than the left 1/3.</td>', 'I would like better balance in exposure and focus.  I also find the right 2/3 more interesting than the left 1/3.', '2020-04-28 12:39:41.000000', NULL, 1),
(7660419, 1247581, 138630, '<td valign="top">Not unrecognizable but no penalty for that and the droplets are exquisite - especially that one in the center that looks almost solid.  I also like the "night sky" kind of look to the background above the pansy.</td>', 'Not unrecognizable but no penalty for that and the droplets are exquisite - especially that one in the center that looks almost solid.  I also like the "night sky" kind of look to the background above the pansy.', '2020-04-28 12:40:58.000000', NULL, 1),
(7660420, 1248135, 138630, '<td valign="top">Very cool!  Normally I would dislike this effect and especially the garish colors, but it''s perfect for this one.  Recognizable as a street scene but certainly abstracted enough for me.</td>', 'Very cool!  Normally I would dislike this effect and especially the garish colors, but it''s perfect for this one.  Recognizable as a street scene but certainly abstracted enough for me.', '2020-04-28 12:43:55.000000', NULL, 1),
(7660421, 1247715, 138630, '<td valign="top">Funny that Mother Nature is a master of both symmetry and abstraction, depending on what you look and . . . and how you look at it.</td>', 'Funny that Mother Nature is a master of both symmetry and abstraction, depending on what you look and . . . and how you look at it.', '2020-04-28 12:45:04.000000', NULL, 1),
(7660422, 1248190, 138630, '<td valign="top">Love the flow and the shapes of this diaphanous creature . . . while I normally enjoy grain, I''m wishing this one had much less of it.</td>', 'Love the flow and the shapes of this diaphanous creature . . . while I normally enjoy grain, I''m wishing this one had much less of it.', '2020-04-28 12:53:24.000000', NULL, 1),
(7660436, 1248049, 100831, '<td valign="top">Whoosh!</td>', 'Whoosh!', '2020-04-28 16:14:03.000000', NULL, 1),
(7660437, 1247686, 100831, '<td valign="top">I keep looking at this. Dark and mysterious and definitely to my liking.</td>', 'I keep looking at this. Dark and mysterious and definitely to my liking.', '2020-04-28 16:15:48.000000', NULL, 1),
(7660440, 1248092, 104230, '<td valign="top">My favorite. I particularly enjoy abstracts based on found objects. <br/> <br/>This says to me "Spring is in the air :-)"</td>', 'My favorite. I particularly enjoy abstracts based on found objects.  This says to me "Spring is in the air :-)"', '2020-04-28 16:30:40.000000', NULL, 1),
